149	    /// (budget permitting); one that ends during the call is restarted and the call retried once. At most one
150	    /// restart per call, so a request lost to a crash is never silently replayed more than once. A `Timeout` on a
151	    /// live session restarts nothing.
152	    ///
153	    /// Worst case is one restart plus one retry: `deadline` applies to each attempt separately, and a restart adds up
154	    /// to 800ms of backoff plus the spawn.
155	    pub async fn request(
156	        &mut self,
157	        method: &str,
158	        params: serde_json::Value,
159	        deadline: Duration,
160	    ) -> Result<TaggedResponse, TscClientError> {
161	        if self.failed {
162	            return Err(self.storm());
163	        }
164	
165	        let restarted_first = self.client.closed().is_some();
166	        if restarted_first {
167	            self.restart().await?;
168	        }
169	
170	        let result = self.client.request(method, params.clone(), deadline).await;
171	        if result.is_err() && !restarted_first && self.client.closed().is_some() {
172	            self.restart().await?;
173	            return self.client.request(method, params, deadline).await;
174	        }
175	        result
176	    }
