182	    async fn restart(&mut self) -> Result<(), TscClientError> {
183	        let now = Instant::now();
184	        self.restart_attempts.retain(|attempt| now.duration_since(*attempt) < RESTART_WINDOW);
185	
186	        if self.restart_attempts.len() as u32 >= MAX_RESTARTS {
