188	            return Err(self.storm());
189	        }
190	
191	        let backoff = BACKOFF_STEPS.get(self.restart_attempts.len()).copied().unwrap_or(BACKOFF_MAX);
192	        // Counted before the spawn and the backoff: a spawn failure or a caller cancelling this call mid-restart still
193	        // burns one attempt, by design.
194	        self.restart_attempts.push(now);
195	        tokio::time::sleep(backoff).await;
196	
197	        // Best-effort cleanup of the crashed process before respawning — it may
198	        // already be gone, so failures here are expected and ignored.
199	        let _ = self.child.start_kill();
200	        let _ = self.child.wait().await;
201	
202	        let (child, client) = spawn_process(&self.config).await?;
203	        self.child = child;
204	        self.client = client;
