1	//! A scenario-driven fake `tsc --api` process for the Lifecycle-gate test suite.
2	//! Scenario is picked via the `FAKE_TSC_SCENARIO` env var (env, not argv, matching
3	//! `crates/cli/src/config.rs`'s precedent for test/caller-controlled input):
4	//! `echo` (default), `never_respond`, `hang_after_n:<N>`, `exit_after:<N>:<code>`,
5	//! `crash_immediately:<code>`, `garbage_bytes`, `bad_content_length`,
6	//! `oversized_frame:<N>`, `truncated_body`, `reorder_ack`, `shutdown_slow:<ms>`, `never_read`,
7	//! `fatal_frame_then_alive`, `fatal_frame_once_then_echo`, `notify_then_echo`, `noisy_stderr`.
8	//!
9	//! Every scenario appends its PID as one line to `<cwd>/fake-tsc-spawns.log` at startup, where `<cwd>` is the value of
10	//! the `--cwd` argument the supervisor passes. Tests read that file to count spawns.
11	//!
12	//! Valid-frame scenarios are built on this crate's own `transport::{ContentLengthDecoder,
13	//! write_frame}`, so this fixture can't drift from what the real client parses;
14	//! bad-frame scenarios intentionally hand-write raw bytes instead.
15	
16	use std::time::Duration;
17	
18	use oxc_react_docgen_tsc_client::transport::{write_frame, ContentLengthDecoder, DEFAULT_MAX_FRAME_BYTES};
19	use tokio::io::AsyncWriteExt;
20	use tokio_stream::StreamExt;
21	use tokio_util::codec::FramedRead;
22	
23	type Requests = FramedRead<tokio::io::Stdin, ContentLengthDecoder>;
24	
25	fn requests() -> Requests {
26	    FramedRead::new(tokio::io::stdin(), ContentLengthDecoder::new(DEFAULT_MAX_FRAME_BYTES))
27	}
28	
29	#[tokio::main]
30	async fn main() {
31	    let prior_spawns = log_spawn();
32	    let scenario = std::env::var("FAKE_TSC_SCENARIO").unwrap_or_else(|_| "echo".to_string());
33	    let mut parts = scenario.splitn(3, ':');
34	    let name = parts.next().unwrap_or("echo");
35	    let arg1 = parts.next();
36	    let arg2 = parts.next();
37	
38	    match name {
39	        "never_respond" => never_respond().await,
40	        "hang_after_n" => hang_after_n(arg1.and_then(|s| s.parse().ok()).unwrap_or(0)).await,
41	        "exit_after" => {
42	            exit_after(arg1.and_then(|s| s.parse().ok()).unwrap_or(0), arg2.and_then(|s| s.parse().ok()).unwrap_or(1))
43	                .await;
44	        }
45	        "crash_immediately" => std::process::exit(arg1.and_then(|s| s.parse().ok()).unwrap_or(1)),
46	        "garbage_bytes" => garbage_bytes().await,
47	        "bad_content_length" => bad_content_length().await,
48	        "oversized_frame" => oversized_frame(arg1.and_then(|s| s.parse().ok()).unwrap_or(usize::MAX)).await,
49	        "truncated_body" => truncated_body().await,
50	        "reorder_ack" => reorder_ack().await,
51	        "notify_then_echo" => notify_then_echo().await,
52	        "noisy_stderr" => noisy_stderr().await,
53	        "never_read" => tokio::time::sleep(Duration::from_secs(3600)).await,
54	        "fatal_frame_then_alive" => fatal_frame_then_alive().await,
55	        "fatal_frame_once_then_echo" if prior_spawns == 0 => fatal_frame_then_alive().await,
56	        "shutdown_slow" => shutdown_slow(arg1.and_then(|s| s.parse().ok()).unwrap_or(10_000)).await,
57	        _ => echo().await,
58	    }
59	}
60	
61	/// Appends this process's PID to `<--cwd>/fake-tsc-spawns.log`. Returns the number of lines already there, so a
62	/// scenario can tell which spawn it is. Logging is skipped (returning 0) when the supervisor passed no `--cwd`.
63	fn log_spawn() -> usize {
64	    let mut args = std::env::args().skip_while(|arg| arg != "--cwd");
65	    let Some(cwd) = args.nth(1) else { return 0 };
66	    let path = std::path::Path::new(&cwd).join("fake-tsc-spawns.log");
67	    let prior = std::fs::read_to_string(&path).map_or(0, |contents| contents.lines().count());
68	    if let Ok(mut file) = std::fs::OpenOptions::new().create(true).append(true).open(&path) {
69	        let _ = std::io::Write::write_all(&mut file, format!("{}\n", std::process::id()).as_bytes());
70	    }
71	    prior
72	}
73	
74	fn request_id(request: &serde_json::Value) -> serde_json::Value {
75	    request.get("id").cloned().unwrap_or(serde_json::Value::Null)
76	}
77	
78	async fn read_request(reader: &mut Requests) -> Option<serde_json::Value> {
79	    match reader.next().await {
80	        Some(Ok(body)) => serde_json::from_slice(&body).ok(),
81	        _ => None,
82	    }
83	}
84	
85	async fn respond<W: tokio::io::AsyncWrite + Unpin>(writer: &mut W, id: &serde_json::Value, result: serde_json::Value) {
86	    let body = serde_json::json!({ "id": id, "result": result });
87	    if let Ok(bytes) = serde_json::to_vec(&body) {
88	        let _ = write_frame(writer, &bytes).await;
89	    }
90	}
91	
92	async fn respond_error<W: tokio::io::AsyncWrite + Unpin>(
93	    writer: &mut W,
94	    id: &serde_json::Value,
95	    code: i64,
96	    message: &str,
97	) {
98	    let body = serde_json::json!({ "id": id, "error": { "code": code, "message": message } });
99	    if let Ok(bytes) = serde_json::to_vec(&body) {
100	        let _ = write_frame(writer, &bytes).await;
101	    }
102	}
103	
104	/// Baseline: echoes `params` back as `result.echo`, or replies with an `error` object
105	/// when `params.fail` is `true` — used to test that one failing call doesn't affect a
106	/// concurrently in-flight sibling (partial project failure).
107	async fn echo() {
108	    let mut reader = requests();
109	    let mut stdout = tokio::io::stdout();
