1	//! Shared helper for the Lifecycle-gate integration tests: builds a `SupervisorConfig`
2	//! pointing at a fresh copy of the `fake-tsc` binary inside a `node_modules/typescript/
3	//! bin/` layout, so `check_version`'s `package.json` lookup finds a real, matching
4	//! version rather than needing every test to fake that out itself.
5	//!
6	//! Each `tests/*.rs` file compiles this module separately as its own crate, so a
7	//! helper unused by one particular test binary is expected, not a real dead-code
8	//! finding — hence the blanket allow below.
9	#![allow(dead_code)]
10	
11	use camino::Utf8PathBuf;
12	use oxc_react_docgen_tsc_client::SupervisorConfig;
13	
14	pub const PINNED_VERSION: &str = "7.1.0-test";
15	
16	/// Returns the temp dir (kept alive for the caller's test duration) and a config ready
17	/// to `Supervisor::spawn`, with `FAKE_TSC_SCENARIO` set to `scenario`.
18	pub fn spawn_fake(scenario: &str) -> (tempfile::TempDir, SupervisorConfig) {
19	    let dir = tempfile::tempdir().expect("create temp dir for fake-tsc layout");
20	    let (tsc_path, cwd) = layout_with_version(&dir, PINNED_VERSION);
21	    let mut config = SupervisorConfig::new(tsc_path, cwd, &[PINNED_VERSION]);
22	    config.extra_env.push(("FAKE_TSC_SCENARIO".to_string(), scenario.to_string()));
23	    (dir, config)
24	}
25	
26	/// Number of processes the fake has started in `cwd`: one line per spawn in `fake-tsc-spawns.log`.
27	pub fn spawn_count(cwd: &camino::Utf8Path) -> usize {
28	    std::fs::read_to_string(cwd.join("fake-tsc-spawns.log")).map_or(0, |contents| contents.lines().count())
29	}
30	
31	/// Waits until the fake has logged at least `at_least` spawns, then lets a spawn that should not have happened show
32	/// up. A child that is slow to start may not have logged yet when a short-deadline request has already returned.
33	pub async fn settled_spawn_count(cwd: &camino::Utf8Path, at_least: usize) -> usize {
34	    let give_up = std::time::Instant::now() + std::time::Duration::from_secs(5);
35	    while spawn_count(cwd) < at_least && std::time::Instant::now() < give_up {
36	        tokio::time::sleep(std::time::Duration::from_millis(20)).await;
37	    }
38	    tokio::time::sleep(std::time::Duration::from_millis(300)).await;
39	    spawn_count(cwd)
40	}
41	
42	/// Builds the `node_modules/typescript/{package.json,bin/tsc}` layout with the given
43	/// version string and a copy of the real `fake-tsc` binary at `bin/tsc`. Returns
44	/// `(tsc_path, cwd)`.
45	pub fn layout_with_version(dir: &tempfile::TempDir, version: &str) -> (Utf8PathBuf, Utf8PathBuf) {
46	    let typescript_dir = dir.path().join("node_modules").join("typescript");
47	    let bin_dir = typescript_dir.join("bin");
48	    std::fs::create_dir_all(&bin_dir).expect("create node_modules/typescript/bin");
49	    std::fs::write(typescript_dir.join("package.json"), format!(r#"{{"version": "{version}"}}"#))
50	        .expect("write package.json");
51	
52	    let fake_tsc_src = std::path::PathBuf::from(env!("CARGO_BIN_EXE_fake-tsc"));
53	    let tsc_dest = bin_dir.join(if cfg!(windows) { "tsc.exe" } else { "tsc" });
54	    std::fs::copy(&fake_tsc_src, &tsc_dest).expect("copy fake-tsc binary into place");
55	
56	    (
57	        Utf8PathBuf::from_path_buf(tsc_dest).expect("temp path is UTF-8"),
58	        Utf8PathBuf::from_path_buf(dir.path().to_path_buf()).expect("temp path is UTF-8"),
59	    )
60	}
61	
62	/// Same layout, but without ever placing a binary at `bin/tsc` — for the missing-binary
63	/// case.
64	pub fn layout_without_binary(dir: &tempfile::TempDir, version: &str) -> (Utf8PathBuf, Utf8PathBuf) {
65	    let typescript_dir = dir.path().join("node_modules").join("typescript");
66	    std::fs::create_dir_all(&typescript_dir).expect("create node_modules/typescript");
67	    std::fs::write(typescript_dir.join("package.json"), format!(r#"{{"version": "{version}"}}"#))
68	        .expect("write package.json");
69	    let tsc_path = typescript_dir.join("bin").join(if cfg!(windows) { "tsc.exe" } else { "tsc" });
70	    (
71	        Utf8PathBuf::from_path_buf(tsc_path).expect("temp path is UTF-8"),
72	        Utf8PathBuf::from_path_buf(dir.path().to_path_buf()).expect("temp path is UTF-8"),
73	    )
74	}
75

