mod common;

use std::time::{Duration, Instant};

use oxc_react_docgen_tsc_client::{Supervisor, TscClientError};
use serde_json::json;

// AC-12 exactly as written in the spec (exit_after:1:7 fixture).
#[tokio::test]
async fn ac12_as_written_exit_after() {
    let (_dir, config) = common::spawn_fake("exit_after:1:7");
    let mut supervisor = Supervisor::spawn(config).await.expect("spawn");
    let stale = supervisor.client();
    supervisor.request("a", json!({}), Duration::from_secs(2)).await.expect("first");
    let second = supervisor.request("b", json!({}), Duration::from_secs(2)).await;
    assert!(second.is_ok(), "second must restart and succeed: {second:?}");
    let start = Instant::now();
    let r = stale.request("ping", json!({}), Duration::from_secs(2)).await;
    let el = start.elapsed();
    assert!(el < Duration::from_millis(100), "{el:?}");
    let ok_variant = matches!(r, Err(TscClientError::Crashed { .. } | TscClientError::Write(_)));
    assert!(ok_variant, "{r:?}");
    let c = stale.closed();
    assert_eq!(
        std::mem::discriminant(c.as_ref().unwrap()),
        std::mem::discriminant(r.as_ref().unwrap_err()),
        "closed={c:?} r={r:?}"
    );
    supervisor.client().request("ping", json!({}), Duration::from_secs(2)).await.expect("live");
}

// A child that stops reading stdin but exits on EOF: shutdown with a clone held and the writer blocked mid-write
// must still close stdin promptly (writer drops stdin from inside a blocked write).
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn shutdown_mid_blocked_write_closes_stdin() {
    // hang_after_n:0 reads everything; use a scenario that stops reading: none exits on EOF while not reading,
    // so this probes via timing only: never_read + measure that the writer task released stdin (child not observable).
    let (_dir, config) = common::spawn_fake("never_read");
    let supervisor = Supervisor::spawn(config).await.expect("spawn");
    let client = supervisor.client();
    let _ = client.request("big", json!({ "blob": "x".repeat(1024 * 1024) }), Duration::from_millis(100)).await;
    let start = Instant::now();
    let status = supervisor.shutdown().await.expect("shutdown");
    eprintln!("never_read shutdown {:?} status {status:?}", start.elapsed());
}

// Concurrency stress on the close/insert race: many requests racing a crash; none may hit Timeout.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn requests_racing_a_crash_never_time_out() {
    for _ in 0..20 {
        let (_dir, config) = common::spawn_fake("exit_after:1:7");
        let supervisor = Supervisor::spawn(config).await.expect("spawn");
        let client = supervisor.client();
        let mut set = tokio::task::JoinSet::new();
        for n in 0..32 {
            let c = client.clone();
            set.spawn(async move { c.request("x", json!({ "n": n }), Duration::from_secs(3)).await });
        }
        let results = set.join_all().await;
        for r in &results {
            assert!(!matches!(r, Err(TscClientError::Timeout { .. })), "timeout in race: {r:?}");
        }
        assert!(client.closed().is_some());
    }
}

